import{_ as c,O as s,H as n,f as d,b as a,j as r,k as o,i}from"./chunks/framework.DfbB1OsU.js";const y=JSON.parse('{"title":"Switzerland: all indicators","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Switzerland: all indicators | trendEcon"}],["meta",{"property":"og:description","content":"Daily economic indicators from Google searches"}],["meta",{"property":"og:url","content":"https://www.trendecon.org/indicators"}],["meta",{"name":"twitter:title","content":"Switzerland: all indicators | trendEcon"}],["meta",{"name":"twitter:description","content":"Daily economic indicators from Google searches"}]]},"headers":[],"relativePath":"indicators.md","filePath":"indicators.md"}'),l={name:"indicators.md"},h={class:"indicator-grid"};function m(g,t,p,f,u,b){const e=s("TrendChart");return n(),d("div",null,[t[0]||(t[0]=a("h1",{id:"switzerland-all-indicators",tabindex:"-1"},[r("Switzerland: all indicators "),a("a",{class:"header-anchor",href:"#switzerland-all-indicators","aria-label":'Permalink to "Switzerland: all indicators"'},"​")],-1)),t[1]||(t[1]=a("p",null,[r("Alongside the headline "),a("a",{href:"/"},"trendEcon index"),r(", we track a set of more specific consumer indicators, each built from a basket of related Google search terms and processed the same way (daily, seasonally adjusted). They offer a more granular read on different parts of consumer behaviour.")],-1)),a("div",h,[o(e,{series:"ch/trendecon",title:"Perceived Economic Situation (headline)",height:"300px"}),o(e,{series:"ch/inflationrate",title:"Perceived Inflation",height:"300px"}),o(e,{series:"ch/luxury",title:"Watches & Jewellery",height:"300px"}),o(e,{series:"ch/mobility",title:"Mobility",height:"300px"}),o(e,{series:"ch/travel",title:"Travel Abroad",height:"300px"}),o(e,{series:"ch/social",title:"Cultural Events",height:"300px"}),o(e,{series:"ch/garden",title:"Gardening & Home Improvement",height:"300px"}),o(e,{series:"ch/homeoffice",title:"Home Office",height:"300px"}),o(e,{series:"ch/clothing",title:"Clothing & Shoes",height:"300px"}),o(e,{series:"ch/fooddelivery",title:"Food Delivery",height:"300px"})]),t[2]||(t[2]=i('<h2 id="what-each-index-measures" tabindex="-1">What each index measures <a class="header-anchor" href="#what-each-index-measures" aria-label="Permalink to &quot;What each index measures&quot;">​</a></h2><p>Each index aggregates a basket of Google search terms into one daily, seasonally adjusted series. The seasonally adjusted CSVs can be downloaded from the <a href="https://github.com/trendecon/data" target="_blank" rel="noreferrer">data repository</a>.</p><div class="kw-ref"><p><strong>Perceived Economic Situation.</strong> Search terms that reflect worries about the economy, such as <em>Wirtschaftskrise</em> (economic crisis). Keywords: <code>Wirtschaftskrise</code> <code>Kurzarbeit</code> <code>arbeitslos</code> <code>Insolvenz</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/trendecon_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Perceived Inflation.</strong> Searches about prices and the cost of living. Keywords: <code>inflation</code> <code>preise</code> <code>benzinpreis</code> <code>mietzins</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/inflationrate_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Watches &amp; Jewellery.</strong> Stores and brands selling luxury watches and jewellery, plus more general luxury-goods searches. Keywords: <code>christ</code> <code>bucherer</code> <code>uhren</code> <code>uhr</code> <code>swarovski</code> <code>rhomberg</code> <code>juwelier</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/luxury_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Mobility.</strong> Search terms related to ground transportation, such as checking the railway schedule or calling a taxi. Keywords: <code>Fahrplan</code> <code>taxi</code> <code>sixt</code> <code>google maps</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/mobility_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Travel Abroad.</strong> Search terms used to book flights and holidays. Keywords: <code>städtetrip</code> <code>flug buchen</code> <code>günstige flüge</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/travel_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Cultural Events.</strong> Searches related to concerts, theatres, cinema and ticket providers for such events. Keywords: <code>Kino</code> <code>Theater</code> <code>Cinema</code> <code>ticketcorner</code> <code>starticket</code> <code>oper</code> <code>konzert</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/social_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Gardening &amp; Home Improvement.</strong> Stores selling materials for home improvement, such as building materials, garden accessories and electrical supplies. Keywords: <code>Heim+Hobby</code> <code>Bau+Hobby</code> <code>Do it + Garden</code> <code>Do it Migros</code> <code>Jumbo</code> <code>Landi</code> <code>Gartencenter</code> <code>Bauhaus</code> <code>Hornbach</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/garden_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Home Office.</strong> Google searches related to working from home. Keywords: <code>headset</code> <code>monitor</code> <code>maus</code> <code>hdmi</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/homeoffice_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Clothing &amp; Shoes.</strong> Clothing and shoe stores and general searches for buying clothes and shoes; people often google the brands directly. Keywords: <code>Mango</code> <code>Zara</code> <code>H&amp;M</code> <code>PKZ</code> <code>Blue Tomato</code> <code>Dosenbach</code> <code>Schuhe kaufen</code> <code>Ochsner Schuhe</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/clothing_sa.csv" target="_blank" rel="noreferrer">CSV</a></p><p><strong>Food Delivery.</strong> Searches related to take away and ordering pizza. Keywords: <code>take away</code> <code>takeaway</code> <code>pizza bestellen</code> <code>dieci pizza</code>. <a href="https://raw.githubusercontent.com/trendecon/data/master/data/ch/fooddelivery_sa.csv" target="_blank" rel="noreferrer">CSV</a></p></div><h2 id="blog-2020–21" tabindex="-1">Blog (2020–21) <a class="header-anchor" href="#blog-2020–21" aria-label="Permalink to &quot;Blog (2020–21)&quot;">​</a></h2><p>During the pandemic we used these indicators to follow how Swiss consumers reacted, from pets and home-office gear to masks, football and dining out. The posts and their charts cover 2020–21 and are kept here as an archive.</p><ul><li><a href="/blog/swiss-economy-today.html">How is the Swiss economy doing today?</a> · 25 May 2020</li><li><a href="/blog/large-events.html">Large events will be allowed soon, but will people show up?</a> · 24 Aug 2020</li><li><a href="/blog/mobility.html">Still a long way to go</a> · 26 Aug 2020</li><li><a href="/blog/demand-shifts.html">Back to normal or permanent shifts in demand?</a> · 2 Sep 2020</li><li><a href="/blog/culinary.html">Culinary consumption patterns before, during and after the lockdown</a> · 3 Sep 2020</li><li><a href="/blog/football.html">Football is back! But what about the fans?</a> · 18 Sep 2020</li><li><a href="/blog/masks.html">How do Swiss consumers cope with masks?</a> · 21 Oct 2020</li><li><a href="/blog/home-office-black-friday.html">A new indicator for working from home and what Black Friday has to do with it</a> · 1 Dec 2020</li><li><a href="/blog/home-office-pet.html">The home office employee&#39;s best companion</a> · 8 Jan 2021</li></ul>',6))])}const k=c(l,[["render",m]]);export{y as __pageData,k as default};
